import React from "react";
import { action } from "@storybook/addon-actions";
import Search from "@material-design-icons/svg/filled/search.svg?react";
import Button from "../Button";
import FormControl from "../Form/FormControl";
import IconButton from "../IconButton";
import Stack from "../Stack";
import Input from "./Input";
import type { Meta, StoryObj } from "@storybook/react";
import withDarkMode from "../../lib/utils/storybookDecorators";
import { Visibility, VisibilityOff } from "@airbus/icons/react";

const meta: Meta<typeof Input> = {
  id: "Components/Input",
  title: "Components/Input Field",
  component: Input,
  args: {
    placeholder: "Placeholder",
  },
  argTypes: {
    endAdornment: { control: false },
    inputRef: { control: false },
    onChange: { control: false },
    onKeyDown: { control: false },
    onKeyUp: { control: false },
    startAdornment: { control: false },
  },
  render: (args) => <Input onChange={action("onChange")} {...args} />,
};

export default meta;
type Story = StoryObj<typeof Input>;

export const Basic: Story = {
  tags: ["visual-test"],
};

export const Status: Story = {
  render: () => (
    <Stack spacing="2-x">
      <Input value="Disabled text" disabled />
      <Input value="ReadOnly text" readOnly />
      <FormControl info helpText="Do you mean gmail.com ?" required>
        <Input value="john@jmail.com" />
      </FormControl>
      <FormControl error errorText="Invalid email" required>
        <Input value="@john" />
      </FormControl>
      <FormControl success successText="Username available" required>
        <Input value="john" />
      </FormControl>
    </Stack>
  ),
};

export const Dark: Story = {
  tags: ["visual-test"],
  decorators: [withDarkMode],
  render: () => (
    <Stack spacing="2-x">
      <Input value="Disabled text" disabled />
      <Input value="ReadOnly text" readOnly />
      <FormControl
        info
        helpText="Must be available"
        required
        placeholder="Type your username"
      >
        <Input />
      </FormControl>
      <FormControl error errorText="Invalid email" required>
        <Input value="@john" />
      </FormControl>
      <FormControl success successText="Username available" required>
        <Input value="john" />
      </FormControl>
    </Stack>
  ),
};

export const Size: Story = {
  render: () => (
    <Stack spacing="2-x">
      <Input value="XLarge" size="xlarge" />
      <Input value="Large" size="large" />
      <Input value="Medium (default)" />
      <Input value="Small" size="small" />
      <Input value="XSmall" size="xsmall" />
    </Stack>
  ),
};

export const Adornment: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const [showPassword, setShowPassword] = React.useState(false);
    return (
      <Stack spacing="2-x" wrapChildren>
        <Input placeholder="Search" startAdornment={<Search />} />
        <Input
          placeholder="Search"
          endAdornment={
            <IconButton variant="ghost" size="small" aria-label="Search">
              <Search />
            </IconButton>
          }
        />
        <Input
          placeholder="Password"
          value="password"
          type={showPassword ? "text" : "password"}
          endAdornment={
            <IconButton
              variant="ghost"
              size="small"
              onClick={() => setShowPassword(!showPassword)}
              aria-label={showPassword ? "Hide password" : "Show password"}
            >
              {showPassword ? <Visibility /> : <VisibilityOff />}
            </IconButton>
          }
        />
        <Input
          placeholder="Search"
          size="xsmall"
          endAdornment={
            <IconButton variant="ghost" size="xsmall" aria-label="Search">
              <Search />
            </IconButton>
          }
        />
        <Input
          placeholder="Search"
          size="small"
          endAdornment={
            <IconButton variant="ghost" size="small" aria-label="Search">
              <Search />
            </IconButton>
          }
        />
        <Input
          placeholder="Search"
          size="large"
          endAdornment={
            <IconButton variant="ghost" aria-label="Search">
              <Search />
            </IconButton>
          }
        />
        <Input
          placeholder="Search"
          size="xlarge"
          endAdornment={
            <IconButton variant="ghost" aria-label="Search">
              <Search />
            </IconButton>
          }
        />
      </Stack>
    );
  },
};

export const Controlled: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const [stringValue, setStringValue] = React.useState("");
    const [numberValue, setNumberValue] = React.useState("");
    const reset = () => {
      setStringValue("");
      setNumberValue("");
    };
    return (
      <Stack spacing="2-x" className="w-288">
        <Input
          placeholder="String input"
          value={stringValue}
          onChange={(_, val) => setStringValue(val)}
        />
        <Input
          placeholder="Number input"
          type="number"
          value={numberValue}
          onChange={(_, val) => setNumberValue(val)}
        />
        <Button variant="primary" onClick={reset}>
          reset
        </Button>
      </Stack>
    );
  },
};
